#include "erl/System.h"
#include "erl/Formatters.h"
#include <iomanip>
#include <sstream>
namespace erl {
bool ReliefHub::addDepot(const DistributionDepot&d){return depots_.emplace(d.id(),d).second;} bool ReliefHub::addVehicle(std::unique_ptr<ReliefVehicle>v){if(!v)return false;return vehicles_.emplace(v->id(),std::move(v)).second;} bool ReliefHub::addMission(const ReliefMission&m){if(mission(m.id()))return false;missions_.push_back(m);return true;}
DistributionDepot*ReliefHub::depot(const std::string&i){auto x=depots_.find(i);return x==depots_.end()?nullptr:&x->second;} const DistributionDepot*ReliefHub::depot(const std::string&i)const{auto x=depots_.find(i);return x==depots_.end()?nullptr:&x->second;} ReliefVehicle*ReliefHub::vehicle(const std::string&i){auto x=vehicles_.find(i);return x==vehicles_.end()?nullptr:x->second.get();} const ReliefVehicle*ReliefHub::vehicle(const std::string&i)const{auto x=vehicles_.find(i);return x==vehicles_.end()?nullptr:x->second.get();} ReliefMission*ReliefHub::mission(const std::string&i){for(auto&x:missions_)if(x.id()==i)return &x;return nullptr;} const ReliefMission*ReliefHub::mission(const std::string&i)const{for(const auto&x:missions_)if(x.id()==i)return &x;return nullptr;}
DispatchResult ReliefHub::dispatchMission(const std::string&m,const std::string&v){auto*mi=mission(m);auto*ve=vehicle(v);if(!mi||!ve)return{false,"Mission or vehicle not found"};auto*de=depot(mi->originDepot());if(!de)return{false,"Mission origin depot not found"};auto r=DispatchCoordinator::dispatch(*mi,*de,*ve);if(r.success)history_.push_back(m+":"+v+":"+r.message);return r;}
std::string ReliefHub::auditReport()const{std::ostringstream r;r<<"ERL-HUB DISPATCH AUDIT\n"<<tableSeparator<<tableRow<<std::left<<std::setw(16)<<"Mission ID"<<tableRow<<std::setw(16)<<"Type"<<tableRow<<std::setw(16)<<"Status"<<tableRow<<std::setw(16)<<"Vehicle"<<"|\n"<<tableSeparator;for(const auto&m:missions_)r<<tableRow<<std::setw(16)<<m.id()<<tableRow<<std::setw(16)<<toString(m.type())<<tableRow<<std::setw(16)<<toString(m.status())<<tableRow<<std::setw(16)<<(m.assignedVehicleId().empty()?"-":m.assignedVehicleId())<<"|\n";return r.str();}
void ReliefHub::loadDemoScenario(){clear();DistributionDepot d("D-01","Central Relief Depot",12000);d+=ReliefCargo("MED-KIT","medical",100,5,1);d+=ReliefCargo("WATER","water",500,1,2);d+=ReliefCargo("TENT","shelter",50,20,2);addDepot(d);addVehicle(makeVehicle("Ground","V-101","MAIT Response",2500,600,{28.61,77.23}));addVehicle(makeVehicle("Aerial","V-202","Air Relief",800,400,{28.61,77.23}));addVehicle(makeVehicle("Amphibious","V-303","River Relief",1500,300,{28.61,77.23}));addMission(ReliefMission("M-1001",MissionType::Medical,"D-01","Ward 7","MED-KIT",20,60,"road",1));addMission(ReliefMission("M-1002",MissionType::Shelter,"D-01","Camp 4","TENT",10,35,"road",2));addMission(ReliefMission("M-1003",MissionType::Water,"D-01","Flood Zone","WATER",100,20,"flooded",1));if(auto*m=mission("M-1001"))IncidentCommander::overrideCriticalTriage(*m,9);}
void ReliefHub::clear(){depots_.clear();vehicles_.clear();missions_.clear();history_.clear();} bool ReliefHub::save(const std::string&p,std::string&e)const{return BinaryPersistence::save(*this,p,e);} bool ReliefHub::load(const std::string&p,std::string&e){return BinaryPersistence::load(*this,p,e);}
}

